<?php
namespace Modules\Ran\Http\Requests;use Illuminate\Foundation\Http\FormRequest;
class PurchaseRequest extends FormRequest{public function authorize():bool{return auth()->check();}public function rules():array{return ['purchase_date'=>'required|date','supplier_contact_id'=>'required|integer','supplier_invoice_no'=>'nullable|string|max:100','discount_amount'=>'nullable|numeric|min:0','tax_amount'=>'nullable|numeric|min:0','notes'=>'nullable|string|max:2000','lines'=>'required|array|min:1','lines.*.item_id'=>'required|integer','lines.*.description'=>'nullable|string|max:255','lines.*.quantity'=>'required|numeric|min:0.0001','lines.*.gross_weight'=>'nullable|numeric|min:0','lines.*.net_weight'=>'nullable|numeric|min:0','lines.*.stone_weight'=>'nullable|numeric|min:0','lines.*.unit_cost'=>'required|numeric|min:0','lines.*.lot_no'=>'nullable|string|max:60','lines.*.serial_no'=>'nullable|string|max:100','lines.*.sale_price'=>'nullable|numeric|min:0'];}}
